def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    resp_D_num = 0
    resp_D_den = 0

    for i in range(n):
        a, b = history[i]
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1
        if i > 0:
            prev_my = history[i - 1][0]
            if prev_my == 'D':
                resp_D_den += 1
                if b == 'D':
                    resp_D_num += 1

    opp_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_run += 1
        else:
            break

    opp_c_run = 0
    if last_opp == 'C':
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'C':
                opp_c_run += 1
            else:
                break

    my_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_run += 1
        else:
            break

    my_c_run = 0
    if last_my == 'C':
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'C':
                my_c_run += 1
            else:
                break

    w = 10 if n >= 10 else n
    recent_opp_d = 0
    for i in range(n - w, n):
        if history[i][1] == 'D':
            recent_opp_d += 1

    hostile = (opp_d_run >= 8 and recent_opp_d >= 8 and opp_d * 2 > n)
    low_retal = (resp_D_den == 0) or (resp_D_num * 3 <= resp_D_den * 2)

    if last_opp == 'D':
        if last_my == 'C':
            if (not hostile) and 1 <= my_c_run <= 2 and opp_d_run >= 4 and opp_d_run <= 8:
                return 'C'

            if (not hostile) and opp_d_run == 1 and my_d == 0:
                if opp_d == 1 or (n >= 10 and opp_d * 5 <= n):
                    return 'C'

            return 'D'

        if (not hostile) and opp_d_run <= 6:
            if my_d_run >= 3 or (my_d_run >= 2 and opp_d_run >= 4):
                return 'C'
        return 'D'

    if last_my == 'D':
        if n >= 2 and history[-2][1] == 'D':
            return 'C'

        if (not hostile) and low_retal:
            if resp_D_den <= 2 or opp_d * 4 < n * 3:
                return 'D'
        return 'C'

    if opp_d == 0 and my_d == 0 and n >= 12:
        return 'D'

    if (not hostile) and opp_c_run >= 4 and my_d >= 1 and low_retal:
        if n < 96 and opp_d * 3 <= n * 2:
            return 'D'

    return 'C'
